// Variant B: "Take wall + run tray": takes are a grid of cards (generation form is a card too);
// cost lives in a docked run tray that expands into an itemised, editable ticket when confirmation is needed.
ACT.clearcmp = () => { S.ui.compare = []; };
ACT.dropline = d => { const c = S.ui.confirm; c.items = c.items.filter((_, i) => i !== +d.i); if (!c.items.length) S.ui.confirm = null; else c.ev = evaluate(c.items, c.opts); };
const VB = (() => {
  const tray = () => {
    const c = S.ui.confirm; const running = S.jobs.length; const failed = S.shots.filter(s => s.failed).length;
    const miss = sceneMissingItems(S.ui.model);
    if (c) {
      return `<div style="position:sticky;bottom:0;background:var(--p2);border-top:1px solid #3d6aaa;padding:12px 16px;z-index:20"><div class="row"><b>Review before starting</b><span class="chip warn">${c.ev.reasons[0]}</span><span class="grow"></span><span class="mu xs">${money(CAP - S.spent)} left today</span></div>
      <div class="col" style="gap:3px;margin:8px 0">${c.items.map((i, k) => `<div class="row" style="padding:3px 8px;background:var(--p1);border-radius:5px"><span class="grow">${i.label}</span><span class="price">${i.price == null ? 'price unavailable' : money(i.price)}</span><button class="sm ghost" title="Leave this out" data-act="dropline" data-i="${k}">✕</button></div>`).join('')}</div>
      <div class="xs mu">${c.ev.reasons.slice(1).map(r => r + ' · ').join('')}One billable run per generation. Runs in the background.</div>
      <div class="row" style="margin-top:8px"><button class="pri" data-act="go_confirm">Start ${c.ev.count} · ${c.ev.total ? money(c.ev.total) : 'price unavailable'}</button><button class="ghost" data-act="no_confirm">Cancel</button></div></div>`;
    }
    const jobs = S.ui.trayOpen ? `<div class="col" style="gap:4px;margin-top:8px">${S.jobs.map(j => `<div class="row"><b>${shot(j.shot).label}</b><div class="prog grow"><i style="width:${j.progress}%"></i></div><button class="sm ghost" data-act="cancel" data-job="${j.id}">Cancel</button></div>`).join('') || '<span class="xs mu">Nothing running.</span>'}${S.shots.filter(s => s.failed).map(s => `<div class="row"><b>${s.label}</b><span class="grow xs" style="color:var(--bad)">${s.failed.reason} ${s.failed.billed === 'maybe' ? 'May have been charged.' : ''}</span><button class="sm" data-act="retry" data-shot="${s.id}">Retry ${money(priceOf(s, s.failed.model))}</button></div>`).join('')}</div>` : '';
    return `<div style="position:sticky;bottom:0;background:var(--p1);border-top:1px solid var(--ln);padding:8px 16px;z-index:20"><div class="row"><button class="ghost sm" data-act="ui" data-key="trayOpen" data-val="">${S.ui.trayOpen ? '▾' : '▴'} Activity: ${running} running${failed ? `, <span style="color:var(--bad)">${failed} failed</span>` : ''}</button><span class="grow"></span><button class="sm" data-act="genScene" ${miss.length ? '' : 'disabled'}>Generate ${miss.length} missing in scene · <span class="price">${money(miss.reduce((a, x) => a + (x.price || 0), 0))}</span></button><button class="sm" data-act="genFilm">Whole film…</button></div>${jobs}</div>`;
  };
  function card(s, t) {
    const i = S.shots.indexOf(s); const prev = S.shots[i - 1], next = S.shots[i + 1]; const ctx = S.ui.ctx;
    const stage = ctx
      ? `<div class="row" style="gap:2px"><div class="poster grow" style="background-image:${prev && prev.sel ? posterOf(prev, selTake(prev)) : 'none'};opacity:.55;aspect-ratio:9/12"></div><div class="poster ${t.id === s.sel ? 'sel' : ''}" style="background-image:${posterOf(s, t)};width:56%;aspect-ratio:16/12"></div><div class="poster grow" style="background-image:${next && next.sel ? posterOf(next, selTake(next)) : 'none'};opacity:.55;aspect-ratio:9/12"></div></div>`
      : `<div class="poster ${S.ui.vp === t.id ? 'kb' : ''} ${t.id === s.sel ? 'sel' : ''}" style="background-image:${posterOf(s, t)};cursor:pointer" data-act="ui" data-key="vp" data-val="${S.ui.vp === t.id ? 0 : t.id}"><span class="tc">${t.dur || s.dur}s</span>${t.id === s.sel ? `<span class="tl" style="color:#9fd">${s.final ? '🔒 final' : 'selected'}</span>` : ''}</div>`;
    return `<div class="col" style="gap:6px">${stage}<div class="row xs"><b>Take ${t.n}</b><span class="mu">${t.model}</span>${t.late ? '<span class="chip">arrived after cancel</span>' : ''}${t.guidance ? `<span class="dim" title="${t.guidance}">guided</span>` : ''}</div>
    <div class="row">${s.sel === t.id ? `<button class="sm" style="border-color:var(--ac)" data-act="deselect" data-shot="${s.id}">✓ Picked</button>${s.final ? '' : `<button class="sm ghost" data-act="final" data-shot="${s.id}">Mark final</button>`}${s.final ? `<button class="sm ghost" data-act="final" data-shot="${s.id}">Unlock</button>` : ''}` : `<button class="pri sm" data-act="select" data-shot="${s.id}" data-take="${t.id}">Pick</button>`}<label class="row xs mu" style="gap:3px"><input type="checkbox" ${S.ui.compare.includes(t.id) ? 'checked' : ''} data-act="cmp" data-take="${t.id}" data-max="3">compare</label><span class="grow"></span><button class="sm ghost" title="Reject (recoverable)" data-act="reject" data-shot="${s.id}" data-take="${t.id}">✕</button></div></div>`;
  }
  function renderShot(s) {
    const i = S.shots.indexOf(s); const prev = S.shots[i - 1], next = S.shots[i + 1]; const job = jobOf(s);
    const cmp = S.ui.compare.map(id => s.takes.find(x => x.id === id)).filter(Boolean);
    const cmpBar = cmp.length >= 2 ? `<div class="note" style="margin-bottom:14px"><div class="row" style="margin-bottom:6px"><b>Comparing ${cmp.length}</b><span class="grow"></span><button class="sm ghost" data-act="clearcmp">Close</button></div><div class="row" style="gap:8px;align-items:flex-start">${cmp.map(c => `<div class="grow"><div class="poster kb" style="background-image:${posterOf(s, c)}"><span class="tc">Take ${c.n}</span></div><button class="sm" style="margin-top:4px;width:100%" data-act="select" data-shot="${s.id}" data-take="${c.id}">${s.sel === c.id ? '✓ Picked' : 'Pick take ' + c.n}</button></div>`).join('')}</div></div>` : '';
    const live = liveTakes(s); const p = priceOf(s, S.ui.model);
    const newCard = `<div class="col" style="gap:7px;border:1px dashed #44505e;border-radius:8px;padding:10px;background:var(--p1)"><b>${live.length ? 'Another take' : 'First take'}</b>${modelSelect()}${guidanceBox('Guidance (optional)')}<button class="pri" data-act="gen" data-shot="${s.id}" ${job ? 'disabled' : ''}>${live.length ? 'Regenerate' : 'Generate'} · ${p == null ? 'price unavailable' : money(p)}${s.long ? ' · ' + s.long + ' parts' : ''}</button><div class="xs mu">${p != null && p < 2 ? 'One click. Starts right away.' : 'Opens the review ticket below first.'}</div><button class="ghost sm" data-act="ui" data-key="inspect" data-val="">${S.ui.inspect ? '▾' : '▸'} Prompt and references</button>${S.ui.inspect ? inspectBlock(s) : ''}</div>`;
    const ghosts = (job ? `<div class="col"><div class="slate" style="flex-direction:column;gap:6px"><span class="xs">Generating… ${Math.min(99, Math.round(job.progress))}%</span><div class="prog" style="width:70%"><i style="width:${job.progress}%"></i></div></div><div class="row xs mu"><span class="grow">Keep working; we'll tell you.</span><button class="sm ghost" data-act="cancel" data-job="${job.id}">Cancel</button></div></div>` : '') +
      (s.batchPartial && !job ? `<div class="col"><div class="slate" style="flex-direction:column;gap:3px"><b class="xs">${s.batchPartial.done} of ${s.batchPartial.total} parts made</b><span class="xs dim">becomes one take when assembled</span></div><button class="sm" data-act="gen" data-shot="${s.id}">Make part ${s.batchPartial.done + 1} · ${money(priceOf(s, S.ui.model) / s.long)}</button></div>` : '') +
      (s.failed ? `<div class="col"><div class="slate" style="flex-direction:column;gap:3px;border-color:#6b4545"><span class="xs" style="color:var(--bad)">${s.failed.reason}</span><span class="xs dim">${s.failed.billed === 'maybe' ? 'You may have been charged.' : 'Not charged.'}</span></div><div class="row"><button class="sm" data-act="retry" data-shot="${s.id}">Retry · ${money(priceOf(s, s.failed.model))}</button><button class="sm ghost" data-act="dismissfail" data-shot="${s.id}">Dismiss</button></div></div>` : '');
    const rej = rejTakes(s);
    return `<div style="min-height:calc(100vh - 100px);display:flex;flex-direction:column"><div style="padding:14px 16px;flex:1"><div class="row"><div class="grow"><div class="row"><b style="font-size:15px">${s.label} · ${s.title}</b>${oodDot(s)}${stateChip(s)}</div><div class="xs mu">${s.plan} · ${s.dur}s planned</div>${oodPop(s)}</div>${S.returnTo ? '<button class="sm" data-act="back">↩ Back to review</button>' : ''}<label class="row xs mu"><input type="checkbox" ${S.ui.ctx ? 'checked' : ''} data-act="ui" data-key="ctx" data-val=""> show in context (${prev ? prev.label : '–'} · this · ${next ? next.label : '–'})</label><button class="ghost sm" ${prev ? `data-act="go" data-view="shot" data-shot="${prev.id}" data-keep="1"` : 'disabled'}>◀</button><button class="ghost sm" ${next ? `data-act="go" data-view="shot" data-shot="${next.id}" data-keep="1"` : 'disabled'}>▶</button></div>
    <div style="margin-top:14px">${cmpBar}<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:14px">${live.map(t => card(s, t)).join('')}${ghosts}${newCard}</div>
    ${rej.length ? `<div class="xs mu" style="margin-top:14px">Rejected (${rej.length}), recoverable: ${rej.map(r => `Take ${r.n} <button class="sm ghost" data-act="restore" data-shot="${s.id}" data-take="${r.id}">restore</button>`).join(' · ')}</div>` : ''}</div></div>${tray()}`;
  }
  function renderReview() {
    const it = playItems(); const tot = totalDur() || 1; const ci = currentIndex(it); const cu = it[ci]; const scene = S.scope === 'scene';
    const head = `<div class="tabs"><button class="${scene ? 'on' : ''}" data-act="go" data-view="review" data-scope="scene">Scene 7</button><button class="${!scene ? 'on' : ''}" data-act="go" data-view="review" data-scope="film">Whole film</button></div>`;
    const player = `<div style="width:min(520px,48%);flex:none">${stageHTML(cu, `<span class="tl">${tc(S.play.t)} / ${tc(tot)}</span>`)}<div class="prog" style="margin-top:6px"><i style="width:${S.play.t / tot * 100}%"></i></div><div class="row" style="margin-top:6px"><button class="pri" data-act="play">${S.play.on ? '❚❚' : '▶'} ${S.play.on ? 'Pause' : 'Play'}</button><button data-act="nextitem" data-dir="-1">⏮</button><button data-act="nextitem" data-dir="1">⏭</button><label class="row xs mu"><input type="checkbox" ${S.play.skipGaps ? 'checked' : ''} data-act="skipgaps"> skip gaps</label></div></div>`;
    const sheet = it0 => it0.map(x => { const s = x.shot; const stt = state(s); return `<div class="col" style="gap:4px;position:relative">${x.gap ? `<div class="slate" style="cursor:pointer;flex-direction:column;gap:4px" data-act="seek" data-t="${x.start}"><span class="xs">${stt === 'failed' ? 'Failed' : stt === 'generating' ? 'Generating' : stt === 'needs-pick' ? 'Needs a pick' : 'No take'}</span></div>` : `<div class="poster ${cu === x ? 'sel' : ''}" style="background-image:${posterOf(s, x.take)};cursor:pointer" data-act="seek" data-t="${x.start}"><span class="tc">${x.d}s</span></div>`}<div class="row xs"><b>${s.label}</b>${oodDot(s).replace('data-act="oodpop"', 'data-x')}<span class="grow"></span>${stt === 'missing' ? `<button class="sm" data-act="gen" data-shot="${s.id}">Generate ${money(priceOf(s, S.ui.model))}</button>` : ''}<button class="sm ghost" title="Open this shot to fix it" data-act="go" data-view="shot" data-shot="${s.id}" data-ret="1">Fix ↗</button></div></div>`; }).join('');
    let body;
    if (scene) body = `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:10px">${sheet(it)}</div>`;
    else { const f = filmShots(); const by = {}; f.forEach(x => (by[x.scene || 7] = by[x.scene || 7] || []).push(x)); body = `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:8px">${Object.keys(by).map(k => `<div style="background:var(--p1);border:1px solid ${k == 7 ? '#3d6aaa' : 'var(--ln)'};border-radius:8px;padding:8px;cursor:pointer" data-act="go" data-view="review" data-scope="scene"><div class="row xs"><b>Scene ${k}</b><span class="grow"></span><span class="mu">${by[k].filter(x => x.sel).length}/${by[k].length}</span></div><div class="row" style="flex-wrap:wrap;gap:3px;margin-top:6px">${by[k].map(x => `<i title="${x.label}" style="width:12px;height:12px;border-radius:2px;display:block;background:${x.sel ? (x.ood && !x.ood.kept ? '#6f6a4e' : '#3b6a4d') : '#2a3038'};${x.sel ? '' : 'border:1px dashed #4a5561'}"></i>`).join('')}</div></div>`).join('')}</div><div class="xs mu" style="margin-top:8px">Each square is a shot. Click a scene to review it as a sheet. Scene 7 is live; others are mock.</div>`; }
    const issues = S.shots.filter(s => ['missing', 'failed', 'needs-pick'].includes(state(s)) || (s.ood && !s.ood.kept));
    const side = `<div class="grow col"><div class="xs mu">SCENE HEALTH</div><div class="row" style="flex-wrap:wrap">${['selected', 'needs-pick', 'missing', 'failed', 'generating'].map(k => `<span class="chip ${stateCls[k]}">${S.shots.filter(s => state(s) === k || (k === 'selected' && state(s) === 'final')).length} ${stateLabel[k].toLowerCase()}</span>`).join('')}<span class="chip">${sceneStats().ood} possibly out of date</span></div><div class="xs mu">Nothing here blocks playing or exporting. Gaps play as a 2 s slate${S.play.skipGaps ? ' (skipped now)' : ''}.</div>${cu && !cu.shot.mock ? `<button data-act="go" data-view="shot" data-shot="${cu.shot.id}" data-ret="1" style="align-self:flex-start">Fix ${cu.shot.label} ↗</button>` : ''}</div>`;
    return `${head}<div style="padding:14px 16px"><div class="row" style="align-items:flex-start;gap:16px;margin-bottom:16px">${player}${side}</div>${body}</div>${tray()}`;
  }
  return { renderShot, renderReview };
})();
